"use client"

import { createContext, useContext, useState, useEffect, useCallback } from 'react'
import { usePathname, useSearchParams } from 'next/navigation'
import { motion, AnimatePresence } from 'framer-motion'
import { Loader2 } from 'lucide-react'

interface NavigationLoadingContextType {
  isNavigating: boolean
  startNavigation: () => void
  stopNavigation: () => void
}

const NavigationLoadingContext = createContext<NavigationLoadingContextType>({
  isNavigating: false,
  startNavigation: () => {},
  stopNavigation: () => {}
})

export function useNavigationLoading() {
  return useContext(NavigationLoadingContext)
}

export function NavigationLoadingProvider({ children }: { children: React.ReactNode }) {
  const [isNavigating, setIsNavigating] = useState(false)
  const pathname = usePathname()
  const searchParams = useSearchParams()

  // Auto-detect navigation start
  useEffect(() => {
    let timeoutId: NodeJS.Timeout

    const handleStart = () => {
      // Set loading after 100ms to avoid flash for fast loads
      timeoutId = setTimeout(() => {
        setIsNavigating(true)
      }, 100)
    }

    const handleStop = () => {
      clearTimeout(timeoutId)
      setIsNavigating(false)
    }

    // Listen for route changes
    const originalPushState = window.history.pushState
    const originalReplaceState = window.history.replaceState

    window.history.pushState = function(...args) {
      handleStart()
      return originalPushState.apply(window.history, args)
    }

    window.history.replaceState = function(...args) {
      handleStart()
      return originalReplaceState.apply(window.history, args)
    }

    return () => {
      window.history.pushState = originalPushState
      window.history.replaceState = originalReplaceState
      clearTimeout(timeoutId)
    }
  }, [])

  // Stop loading when pathname changes
  useEffect(() => {
    setIsNavigating(false)
  }, [pathname, searchParams])

  const startNavigation = useCallback(() => {
    setIsNavigating(true)
  }, [])

  const stopNavigation = useCallback(() => {
    setIsNavigating(false)
  }, [])

  return (
    <NavigationLoadingContext.Provider value={{ isNavigating, startNavigation, stopNavigation }}>
      {children}

      {/* Global loading indicator */}
      <AnimatePresence>
        {isNavigating && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed top-0 left-0 right-0 z-[100] h-1 bg-gradient-to-r from-primary via-primary/80 to-primary"
          >
            <motion.div
              className="h-full bg-white/30"
              animate={{
                x: ['-100%', '100%']
              }}
              transition={{
                duration: 1,
                repeat: Infinity,
                ease: 'linear'
              }}
            />
          </motion.div>
        )}
      </AnimatePresence>

      {/* Optional center loading spinner for long loads */}
      <AnimatePresence>
        {isNavigating && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ delay: 1 }} // Show after 1 second of loading
            className="fixed inset-0 z-[99] pointer-events-none"
          >
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2">
              <div className="bg-background/80 backdrop-blur-sm rounded-lg p-4 shadow-lg">
                <Loader2 className="h-6 w-6 animate-spin text-primary mx-auto" />
                <p className="text-sm text-muted-foreground mt-2">Loading...</p>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </NavigationLoadingContext.Provider>
  )
}

