"use client"

import Link, { LinkProps } from 'next/link'
import { useRouter } from 'next/navigation'
import { useNavigationLoading } from './navigation-loading-provider'
import { useCallback, MouseEvent, ReactNode } from 'react'

interface OptimizedLinkProps extends Omit<LinkProps, 'onClick'> {
  children: ReactNode
  className?: string
  onClick?: (e: MouseEvent<HTMLAnchorElement>) => void
}

/**
 * Optimized Link component with loading states and prefetching
 * Replaces standard Next.js Link for better UX during navigation
 */
export function OptimizedLink({
  href,
  children,
  className,
  onClick,
  prefetch = true,
  ...props
}: OptimizedLinkProps) {
  const router = useRouter()
  const { startNavigation } = useNavigationLoading()

  const handleClick = useCallback((e: MouseEvent<HTMLAnchorElement>) => {
    // Call custom onClick if provided
    if (onClick) {
      onClick(e)
    }

    // Don't interfere with modified clicks
    if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) {
      return
    }

    // Start loading immediately for better perceived performance
    startNavigation()

    // For external links, don't interfere
    const url = typeof href === 'string' ? href : href.pathname || ''
    if (url.startsWith('http') || url.startsWith('//')) {
      return
    }

    // Use router.push for smoother client-side navigation
    e.preventDefault()
    router.push(url)
  }, [href, onClick, router, startNavigation])

  return (
    <Link
      href={href}
      className={className}
      onClick={handleClick}
      prefetch={prefetch}
      {...props}
    >
      {children}
    </Link>
  )
}

